<?php
declare(strict_types=1);
namespace dyws\Plugins\OpenStreetMap;
use dyws\{Store,ApiError,Catalog};
/** Bounded browser raster, authoritative server totals and filters, shared private archive. */
final class MapPDF {
 public function __construct(private Store $store,private array $config){}
 private static function esc($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
 public function export(array $body):array {
  if(!in_array('order-reporting',$this->store->plugins?->activeIds()??[],true))throw new ApiError('Activate Order Reporting to export and archive map PDFs.',503);
  $root=$this->config['plugins_path']??dirname(__DIR__);foreach(['PdfArchive','PdfIdentity'] as $class){$file=$root.'/order-reporting/'.$class.'.php';if(!is_file($file))throw new ApiError('PDF reporting is unavailable.',503);require_once $file;}
  if(!class_exists(\Dompdf\Dompdf::class)){$autoload=dirname(__DIR__,2).'/vendor/autoload.php';if(is_file($autoload))require_once $autoload;}if(!class_exists(\Dompdf\Dompdf::class))throw new ApiError('PDF export is unavailable.',503);
  $query=$body['query']??null;$layers=$body['layers']??null;$heat=$body['heatmap']??null;$view=$body['view']??null;
  if(!is_array($query)||!is_array($layers)||!array_is_list($layers)||count($layers)>2||array_filter($layers,fn($layer)=>!is_string($layer)||!in_array($layer,['delivery','pickup'],true))||count(array_unique($layers,SORT_STRING))!==count($layers)||!is_bool($heat)||($heat&&!in_array('delivery',$layers,true)))throw new ApiError('Choose valid map layers and filters.');
  $query=array_intersect_key($query,array_flip(['from','to','currency','fulfillment','status','location']));$data=(new OrderMap($this->store,$this->config))->dataset($query);
  if(!is_string($body['snapshotId']??null)||!hash_equals($data['snapshotId'],$body['snapshotId']))throw new ApiError('Orders or locations changed. Refresh the map before exporting.',409);
  if(!is_array($view)||!is_array($view['bounds']??null)||count($view['bounds'])!==4||!array_is_list($view['bounds'])||!is_int($view['zoom']??null)||$view['zoom']<0||$view['zoom']>19)throw new ApiError('Provide a valid map viewport.');
  foreach($view['bounds'] as $i=>$v)if(!is_numeric($v)||!is_finite((float)$v)||abs((float)$v)>($i%2===0?90:540))throw new ApiError('Provide valid viewport coordinates.');
  [$south,$west,$north,$east]=array_map('floatval',$view['bounds']);if($south>=$north||$west>=$east||$east-$west>1080)throw new ApiError('Provide valid viewport bounds.');
  $image=$body['image']??null;if(!is_string($image)||!str_starts_with($image,'data:image/jpeg;base64,')||strlen($image)>245000)throw new ApiError('Use a bounded JPEG map image.');
  $bytes=base64_decode(substr($image,23),true);$size=$bytes===false?false:@getimagesizefromstring($bytes);if(!$size||($size['mime']??'')!=='image/jpeg'||$size[0]<150||$size[1]<150||$size[0]>1600||$size[1]>1600||$size[0]*$size[1]>2000000)throw new ApiError('Use a valid map raster up to 1600 pixels per side.');
  $settings=(new Settings($this->config))->summary();$catalog=Catalog::load($this->config['catalog']);$mapped=$unmapped=0;$value=0;
  foreach($layers as $layer){$mapped+=$data['coverageByLayer'][$layer]['mapped'];$unmapped+=$data['coverageByLayer'][$layer]['unmapped'];}foreach($data['groups'] as $g)if(in_array($g['layer'],$layers,true))$value+=$g['orderedValueExcludingTips'];
  $info=array_intersect_key($catalog,array_flip(['businessName','pickupAddress','businessPhone','businessEmail']));$info['businessWebsite']=$this->config['reporting']['businessWebsite']??'';$scope=$data['scope'];
  $mapView=['query'=>$scope,'layers'=>$layers,'heatmap'=>$heat,'heatSigmaMetres'=>550,'radiusMetres'=>3000,'bounds'=>[$south,$west,$north,$east],'zoom'=>$view['zoom'],'businessPoints'=>$settings['businessPoints'],'snapshotId'=>$data['snapshotId'],'mappedOrders'=>$mapped,'unmappedOrders'=>$unmapped,'omittedOrders'=>$data['omittedOrders'],'imageWidth'=>$size[0],'imageHeight'=>$size[1]];
  $archiveData=['range'=>['from'=>$scope['from'],'to'=>$scope['to']],'previousRange'=>null,'currency'=>$scope['currency'],'fulfillment'=>count($layers)===1?$layers[0]:'all','timeZone'=>$scope['timeZone'],'workingHours'=>$catalog['locationHours']??null,'businessInfo'=>$info,'mapView'=>$mapView];
  $layerNames=$layers?implode(', ',array_map(fn($s)=>$s==='delivery'?'Delivery areas':'Pickup locations',$layers)):'Business location only';$branch=$scope['location']==='*'?'All locations':($scope['location']===''?$catalog['businessName']:$scope['location']);foreach($data['locations'] as $location)if($location['id']===$scope['location'])$branch=$location['name'];
  $scale=min(736/$size[0],285/$size[1]);$width=round($size[0]*$scale,2);$height=round($size[1]*$scale,2);
  $html='<html><head><meta charset="utf-8"><style>@page{margin:22pt 28pt 42pt}body{font:8pt DejaVu Sans;color:#19211c}h1{font-size:18pt;margin:0 0 4pt}p{margin:4pt 0}.scope{font-size:8pt}.map{text-align:center;margin:8pt 0}.note{font-size:7pt;color:#526157}.metrics{font-size:9pt;font-weight:bold;margin:6pt 0}</style></head><body><h1>Order map</h1>'.\dyws\Plugins\OrderReporting\PdfIdentity::header($archiveData,$catalog['businessName']).'<p class="scope">'.self::esc($scope['from'].' to '.$scope['to'].' · '.$scope['currency'].' · '.$scope['timeZone']).'<br>'.self::esc($layerNames.' · Heatmap '.($heat?'on':'off').' · Status: '.str_replace('_',' ',$scope['status']).' · '.$branch).'</p><p class="map"><img src="'.self::esc($image).'" style="width:'.$width.'pt;height:'.$height.'pt"></p><p class="metrics">'.self::esc($mapped.' mapped · '.$unmapped.' without a location · '.$scope['currency'].' '.number_format($value/100,2).' ordered value excluding tips').'</p><p class="note">Selected layer totals cover the whole filtered period; the image shows the captured viewport. Includes cancelled orders in counts; value excludes cancellations and tips.'.($data['omittedOrders']?' '.$data['omittedOrders'].' orders omitted by the 10,000 order limit.':'').'</p><p class="note">'.($data['demo']?'Demonstration records. No real deliveries. ':'').'Delivery points are approximate areas, not exact homes. Heatmap uses relative order density with 550 m smoothing. The 3 km ring is straight line distance. Visual captured in the browser; totals and filters verified by the server. Operational information, not audited accounts. © OpenStreetMap contributors, https://www.openstreetmap.org/copyright</p></body></html>';
  $pdf=new \Dompdf\Dompdf(['isRemoteEnabled'=>false,'isPhpEnabled'=>false,'isJavascriptEnabled'=>false,'defaultFont'=>'DejaVu Sans']);$pdf->setPaper('letter','landscape');$pdf->loadHtml($html,'UTF-8');$pdf->render();$identity=\dyws\Plugins\OrderReporting\PdfIdentity::footer($pdf,$scope['timeZone']);$file=['type'=>'application/pdf','name'=>\dyws\Plugins\OrderReporting\PdfIdentity::prefix($catalog['businessName']).'-order-map-'.$scope['from'].'-'.$scope['to'].'.pdf','content'=>$pdf->output(),'identity'=>$identity];
  $saved=(new \dyws\Plugins\OrderReporting\PdfArchive($this->store,$this->config))->save($file,$archiveData,[],'order-map');$saved['content']=base64_encode($saved['content']);return $saved+['encoding'=>'base64'];
 }
}
